        , POLICY_END_DATE as RISK_EXPIRY_DATE
        , POLICY_STATUS as POLICY_STATUS
        , cast(null as varchar) as TOP_UP_POLICY_INDICATOR
        , cast(null as varchar) as POLICY_TERM
        , cast(null as varchar) as RISK_START_TIME
        , cast(null as varchar) as MASTER_POLICY_REFERENCE
        , cast(null as varchar) as POLICY_TYPE
        , cast(null as varchar) as POLICY_NUMBER
        , cast(null as varchar) as PREMIUM_PAYER_REFERENCE
        , cast(null as varchar) as ISSUE_DATE
        , cast(null as varchar) as POLICY_REMARKS
        , cast(null as varchar) as POLICY_TERM_DAYS
        , cast(null as varchar) as SUM_INSURED_TOTAL
        , cast(null as varchar) as SUM_INSURED_BASIS
        , cast(null as varchar) as COVER_NOTE_REFERENCE
        , cast(null as varchar) as COVER_NOTE_DATE
        , cast(null as varchar) as FIRST_YEAR_INDICATOR
        , cast(null as varchar) as PRODUCT_REFERENCE
        , cast(null as varchar) as POLICY_REFERENCE_NUMBER
        , cast(null as varchar) as ISSUING_ORG_UNIT_CODE
        , cast(null as varchar) as LINE_OF_BUSINESS
        , cast(null as varchar) as ISSUING_CHANNEL_REFERENCE
