        , cast(null as varchar) as CO_INSURANCE_INDICATOR
        , cast(null as varchar) as RISK_END_TIME
        , cast(null as varchar) as MULTI_YEAR_INDICATOR
        , 'BA_HCP_PORT_WORDINGS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hcp_port_wordings') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__BASE_POLICY_REF))) as HUB_POLICY_HK
        , cast(null as varchar) as RISK_INCEPTION_DATE
        , cast(null as varchar) as RISK_EXPIRY_DATE
