        , cast(null as varchar) as FIRST_YEAR_INDICATOR
        , cast(null as varchar) as PRODUCT_REFERENCE
        , cast(null as varchar) as POLICY_REFERENCE_NUMBER
        , cast(null as varchar) as ISSUING_ORG_UNIT_CODE
        , cast(null as varchar) as LINE_OF_BUSINESS
        , cast(null as varchar) as ISSUING_CHANNEL_REFERENCE
        , cast(null as varchar) as RURAL_SECTOR_POLICY_INDICATOR
        , cast(null as varchar) as CO_INSURANCE_INDICATOR
        , RISK_EXPIRY_TIME as RISK_END_TIME
        , cast(null as varchar) as MULTI_YEAR_INDICATOR
        , 'BA_CCP_SUB_MATER_DTLS' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_ba_ccp_sub_mater_dtls') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , TERM_START_DATE as RISK_INCEPTION_DATE
        , TERM_END_DATE as RISK_EXPIRY_DATE
        , POLICY_STATUS as POLICY_STATUS
        , cast(null as varchar) as TOP_UP_POLICY_INDICATOR
