        , cast(null as varchar) as MASTER_POLICY_REFERENCE
        , cast(null as varchar) as POLICY_TYPE
        , cast(null as varchar) as POLICY_NUMBER
        , cast(null as varchar) as PREMIUM_PAYER_REFERENCE
        , POLICY_ISSUE_DATE as ISSUE_DATE
        , cast(null as varchar) as POLICY_REMARKS
        , cast(null as varchar) as POLICY_TERM_DAYS
        , SUM_INSURED as SUM_INSURED_TOTAL
        , cast(null as varchar) as SUM_INSURED_BASIS
        , COVERNOTE_NO as COVER_NOTE_REFERENCE
        , COVERNOTE_DATE as COVER_NOTE_DATE
        , cast(null as varchar) as FIRST_YEAR_INDICATOR
        , cast(null as varchar) as PRODUCT_REFERENCE
        , POLICY_REF as POLICY_REFERENCE_NUMBER
        , cast(null as varchar) as ISSUING_ORG_UNIT_CODE
        , cast(null as varchar) as LINE_OF_BUSINESS
        , cast(null as varchar) as ISSUING_CHANNEL_REFERENCE
        , RURAL_FLAG as RURAL_SECTOR_POLICY_INDICATOR
        , COINS_FLAG as CO_INSURANCE_INDICATOR
        , cast(null as varchar) as RISK_END_TIME
        , cast(null as varchar) as MULTI_YEAR_INDICATOR
        , 'BJAZ_POLICY_SUMMARY' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_policy_summary') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , cast(null as varchar) as RISK_INCEPTION_DATE
        , cast(null as varchar) as RISK_EXPIRY_DATE
        , cast(null as varchar) as POLICY_STATUS
        , cast(null as varchar) as TOP_UP_POLICY_INDICATOR
        , POLICY_PERIOD as POLICY_TERM
        , TERM_START_TIME as RISK_START_TIME
        , cast(null as varchar) as MASTER_POLICY_REFERENCE
        , cast(null as varchar) as POLICY_TYPE
        , cast(null as varchar) as POLICY_NUMBER
        , cast(null as varchar) as PREMIUM_PAYER_REFERENCE
        , cast(null as varchar) as ISSUE_DATE
        , cast(null as varchar) as POLICY_REMARKS
        , cast(null as varchar) as POLICY_TERM_DAYS
        , SUM_INSURED as SUM_INSURED_TOTAL
        , cast(null as varchar) as SUM_INSURED_BASIS
        , COVERNOTE_NO as COVER_NOTE_REFERENCE
        , COVERNOTE_DATE as COVER_NOTE_DATE
        , cast(null as varchar) as FIRST_YEAR_INDICATOR
        , cast(null as varchar) as PRODUCT_REFERENCE
        , cast(null as varchar) as POLICY_REFERENCE_NUMBER
        , cast(null as varchar) as ISSUING_ORG_UNIT_CODE
        , cast(null as varchar) as LINE_OF_BUSINESS
        , cast(null as varchar) as ISSUING_CHANNEL_REFERENCE
        , cast(null as varchar) as RURAL_SECTOR_POLICY_INDICATOR
        , cast(null as varchar) as CO_INSURANCE_INDICATOR
        , cast(null as varchar) as RISK_END_TIME
        , MULTI_YEAR_FLAG as MULTI_YEAR_INDICATOR
        , 'BJAZ_POLICY_BASES_EXTN' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_policy_bases_extn') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
),

resolved as (
    select
        HUB_POLICY_HK,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then RISK_INCEPTION_DATE end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then RISK_INCEPTION_DATE end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then RISK_INCEPTION_DATE end)) as RISK_INCEPTION_DATE,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then RISK_EXPIRY_DATE end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then RISK_EXPIRY_DATE end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then RISK_EXPIRY_DATE end)) as RISK_EXPIRY_DATE,
        coalesce(max(case when SOURCE_RUN = 'opus_health_legacy_v4' then POLICY_STATUS end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then POLICY_STATUS end)) as POLICY_STATUS,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then TOP_UP_POLICY_INDICATOR end) as TOP_UP_POLICY_INDICATOR,
        coalesce(max(case when SOURCE_RUN = 'opus_health_legacy_v4' then POLICY_TERM end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then POLICY_TERM end)) as POLICY_TERM,
        coalesce(max(case when SOURCE_RUN = 'opus_health_legacy_v4' then RISK_START_TIME end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then RISK_START_TIME end)) as RISK_START_TIME,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then MASTER_POLICY_REFERENCE end) as MASTER_POLICY_REFERENCE,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then POLICY_TYPE end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then POLICY_TYPE end)) as POLICY_TYPE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then POLICY_NUMBER end) as POLICY_NUMBER,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then PREMIUM_PAYER_REFERENCE end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PREMIUM_PAYER_REFERENCE end)) as PREMIUM_PAYER_REFERENCE,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then ISSUE_DATE end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then ISSUE_DATE end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then ISSUE_DATE end)) as ISSUE_DATE,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then POLICY_REMARKS end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then POLICY_REMARKS end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then POLICY_REMARKS end)) as POLICY_REMARKS,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then POLICY_TERM_DAYS end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then POLICY_TERM_DAYS end)) as POLICY_TERM_DAYS,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then SUM_INSURED_TOTAL end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then SUM_INSURED_TOTAL end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then SUM_INSURED_TOTAL end)) as SUM_INSURED_TOTAL,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then SUM_INSURED_BASIS end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then SUM_INSURED_BASIS end)) as SUM_INSURED_BASIS,
        coalesce(max(case when SOURCE_RUN = 'opus_health_legacy_v4' then COVER_NOTE_REFERENCE end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then COVER_NOTE_REFERENCE end)) as COVER_NOTE_REFERENCE,
        coalesce(max(case when SOURCE_RUN = 'opus_health_legacy_v4' then COVER_NOTE_DATE end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then COVER_NOTE_DATE end)) as COVER_NOTE_DATE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then FIRST_YEAR_INDICATOR end) as FIRST_YEAR_INDICATOR,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then PRODUCT_REFERENCE end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PRODUCT_REFERENCE end)) as PRODUCT_REFERENCE,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then POLICY_REFERENCE_NUMBER end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then POLICY_REFERENCE_NUMBER end)) as POLICY_REFERENCE_NUMBER,
        max(case when SOURCE_RUN = 'opus_health_v2' then ISSUING_ORG_UNIT_CODE end) as ISSUING_ORG_UNIT_CODE,
        max(case when SOURCE_RUN = 'opus_health_v2' then LINE_OF_BUSINESS end) as LINE_OF_BUSINESS,
        max(case when SOURCE_RUN = 'opus_health_v2' then ISSUING_CHANNEL_REFERENCE end) as ISSUING_CHANNEL_REFERENCE,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then RURAL_SECTOR_POLICY_INDICATOR end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then RURAL_SECTOR_POLICY_INDICATOR end)) as RURAL_SECTOR_POLICY_INDICATOR,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then CO_INSURANCE_INDICATOR end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then CO_INSURANCE_INDICATOR end)) as CO_INSURANCE_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_delta3' then RISK_END_TIME end) as RISK_END_TIME,
        max(case when SOURCE_RUN = 'opus_health_delta3' then MULTI_YEAR_INDICATOR end) as MULTI_YEAR_INDICATOR,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_POLICY_HK
),

hashed as (
    select
        *,
        case when RISK_INCEPTION_DATE is not null or RISK_EXPIRY_DATE is not null or POLICY_STATUS is not null or TOP_UP_POLICY_INDICATOR is not null or POLICY_TERM is not null or RISK_START_TIME is not null or MASTER_POLICY_REFERENCE is not null or POLICY_TYPE is not null or POLICY_NUMBER is not null or PREMIUM_PAYER_REFERENCE is not null or ISSUE_DATE is not null or POLICY_REMARKS is not null or POLICY_TERM_DAYS is not null or SUM_INSURED_TOTAL is not null or SUM_INSURED_BASIS is not null or COVER_NOTE_REFERENCE is not null or COVER_NOTE_DATE is not null or FIRST_YEAR_INDICATOR is not null or PRODUCT_REFERENCE is not null or POLICY_REFERENCE_NUMBER is not null or ISSUING_ORG_UNIT_CODE is not null or LINE_OF_BUSINESS is not null or ISSUING_CHANNEL_REFERENCE is not null or RURAL_SECTOR_POLICY_INDICATOR is not null or CO_INSURANCE_INDICATOR is not null or RISK_END_TIME is not null or MULTI_YEAR_INDICATOR is not null
                     then md5(upper(coalesce(cast(RISK_INCEPTION_DATE as varchar), '') || '|' || coalesce(cast(RISK_EXPIRY_DATE as varchar), '') || '|' || coalesce(cast(POLICY_STATUS as varchar), '') || '|' || coalesce(cast(TOP_UP_POLICY_INDICATOR as varchar), '') || '|' || coalesce(cast(POLICY_TERM as varchar), '') || '|' || coalesce(cast(RISK_START_TIME as varchar), '') || '|' || coalesce(cast(MASTER_POLICY_REFERENCE as varchar), '') || '|' || coalesce(cast(POLICY_TYPE as varchar), '') || '|' || coalesce(cast(POLICY_NUMBER as varchar), '') || '|' || coalesce(cast(PREMIUM_PAYER_REFERENCE as varchar), '') || '|' || coalesce(cast(ISSUE_DATE as varchar), '') || '|' || coalesce(cast(POLICY_REMARKS as varchar), '') || '|' || coalesce(cast(POLICY_TERM_DAYS as varchar), '') || '|' || coalesce(cast(SUM_INSURED_TOTAL as varchar), '') || '|' || coalesce(cast(SUM_INSURED_BASIS as varchar), '') || '|' || coalesce(cast(COVER_NOTE_REFERENCE as varchar), '') || '|' || coalesce(cast(COVER_NOTE_DATE as varchar), '') || '|' || coalesce(cast(FIRST_YEAR_INDICATOR as varchar), '') || '|' || coalesce(cast(PRODUCT_REFERENCE as varchar), '') || '|' || coalesce(cast(POLICY_REFERENCE_NUMBER as varchar), '') || '|' || coalesce(cast(ISSUING_ORG_UNIT_CODE as varchar), '') || '|' || coalesce(cast(LINE_OF_BUSINESS as varchar), '') || '|' || coalesce(cast(ISSUING_CHANNEL_REFERENCE as varchar), '') || '|' || coalesce(cast(RURAL_SECTOR_POLICY_INDICATOR as varchar), '') || '|' || coalesce(cast(CO_INSURANCE_INDICATOR as varchar), '') || '|' || coalesce(cast(RISK_END_TIME as varchar), '') || '|' || coalesce(cast(MULTI_YEAR_INDICATOR as varchar), '')))
                end as SAT_POLICY_HEADER_HASHDIFF
    from resolved
)

select * from hashed
where HUB_POLICY_HK is not null
  and SAT_POLICY_HEADER_HASHDIFF is not null
